        repo.next_id.return_value = 1
        with pytest.raises(ValueError, match="must be a datetime"):
            svc.create("t", due_at="2025-01-01")  # type: ignore[arg-type]

    def test_normalizes_tags(self, svc, repo):
        repo.next_id.return_value = 1
        task = svc.create("t", tags=["Hello", "HELLO", "world"])
        assert [t.name for t in task.tags] == ["hello", "world"]

    def test_with_priority_and_due(self, svc, repo, now):
        repo.next_id.return_value = 1
        due = now + timedelta(days=1)
        task = svc.create("t", priority=TaskPriority.HIGH, due_at=due)
        assert task.priority == TaskPriority.HIGH
        assert task.due_at == due


