from __future__ import annotations

from datetime import datetime, timedelta, timezone

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus
from tasks_api.queries import TaskPage, TaskQuery, TaskQueryError, apply_query

NOW = datetime(2025, 6, 1, 12, 0, 0, tzinfo=timezone.utc)


def _task(id, title="task", status=TaskStatus.PENDING, priority=TaskPriority.MEDIUM,
          due_at=None, tags=None, created_at=None):
    return Task(
        id=id, title=title, status=status, priority=priority,
        due_at=due_at, tags=tags or [],
        created_at=created_at or NOW - timedelta(hours=id),
    )


@pytest.fixture
def tasks():
    return [
        _task(1, "Buy milk", priority=TaskPriority.LOW, tags=[Tag("shopping")]),
        _task(2, "Write tests", priority=TaskPriority.HIGH, tags=[Tag("dev")]),
        _task(3, "Done thing", status=TaskStatus.DONE, priority=TaskPriority.MEDIUM),
        _task(4, "Overdue task", due_at=NOW - timedelta(days=1), tags=[Tag("dev"), Tag("urgent")]),
        _task(5, "Future task", due_at=NOW + timedelta(days=1)),
    ]


class TestFilterStatus:
    def test_pending_only(self, tasks):
        q = TaskQuery(status=TaskStatus.PENDING)
        page = apply_query(tasks, q, NOW)
        assert all(t.status == TaskStatus.PENDING for t in page.items)
        assert page.total == 4

    def test_done_only(self, tasks):
        q = TaskQuery(status=TaskStatus.DONE)
        page = apply_query(tasks, q, NOW)
        assert page.total == 1
        assert page.items[0].id == 3


