        q = TaskQuery(search="buy")
        page = apply_query(tasks, q, NOW)
        assert page.total == 1
        assert page.items[0].id == 1

    def test_whitespace_only_search_ignored(self, tasks):
        q = TaskQuery(search="   ")
        page = apply_query(tasks, q, NOW)
        assert page.total == 5


class TestFilterOverdue:
    def test_overdue_true(self, tasks):
        q = TaskQuery(overdue=True)
        page = apply_query(tasks, q, NOW)
        assert page.total == 1
        assert page.items[0].id == 4

    def test_overdue_false(self, tasks):
        q = TaskQuery(overdue=False)
        page = apply_query(tasks, q, NOW)
        assert all(not t.is_overdue(NOW) for t in page.items)


class TestSort:
