"""Tests for tasks_api.models."""

from datetime import datetime, timezone, timedelta

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus


class TestTag:
    def test_normalizes_name(self):
        assert Tag("  Hello  ").name == "hello"

    def test_rejects_empty(self):
        with pytest.raises(ValueError, match="must not be empty"):
            Tag("   ")

    def test_rejects_non_string(self):
        with pytest.raises(TypeError):
            Tag(123)  # type: ignore[arg-type]

    def test_rejects_too_long(self):
        with pytest.raises(ValueError, match="32 characters"):
            Tag("a" * 33)

    def test_rejects_illegal_chars(self):
        with pytest.raises(ValueError, match="illegal character"):
            Tag("hello world")

    def test_allows_hyphen_underscore(self):
        assert Tag("my-tag_1").name == "my-tag_1"


class TestTaskPriority:
    def test_order_key(self):
        assert TaskPriority.order_key(TaskPriority.HIGH) == 0
        assert TaskPriority.order_key(TaskPriority.MEDIUM) == 1
        assert TaskPriority.order_key(TaskPriority.LOW) == 2


class TestTask:
    def test_is_overdue_true(self):
        now = datetime(2025, 6, 1, 12, 0, 0, tzinfo=timezone.utc)
        task = Task(id=1, title="t", due_at=now - timedelta(hours=1))
        assert task.is_overdue(now) is True

    def test_is_overdue_false_no_due(self):
        now = datetime(2025, 6, 1, 12, 0, 0, tzinfo=timezone.utc)
        task = Task(id=1, title="t")
        assert task.is_overdue(now) is False

    def test_is_overdue_false_done(self):
        now = datetime(2025, 6, 1, 12, 0, 0, tzinfo=timezone.utc)
        task = Task(
            id=1, title="t",
            status=TaskStatus.DONE,
            due_at=now - timedelta(hours=1),
        )
        assert task.is_overdue(now) is False

    def test_is_overdue_false_future(self):
        now = datetime(2025, 6, 1, 12, 0, 0, tzinfo=timezone.utc)
        task = Task(id=1, title="t", due_at=now + timedelta(hours=1))
        assert task.is_overdue(now) is False

"""Tests for tasks_api.service.TaskService with mocked repository."""

from __future__ import annotations

from datetime import datetime, timedelta, timezone
from unittest.mock import Mock

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus
from tasks_api.repository import TaskRepository
from tasks_api.service import TaskNotFoundError, TaskService


@pytest.fixture
def now():
    return datetime(2025, 6, 1, 12, 0, 0, tzinfo=timezone.utc)


@pytest.fixture
def clock(now):
    return lambda: now


@pytest.fixture
def repo():
    return Mock(spec=TaskRepository)


@pytest.fixture
def svc(repo, clock):
    return TaskService(repo, now=clock)


class TestCreate:
    def test_creates_task(self, svc, repo, now):
        repo.next_id.return_value = 1
        task = svc.create("My task")
        repo.add.assert_called_once()
        assert task.title == "My task"
        assert task.status == TaskStatus.PENDING
        assert task.created_at == now

    def test_strips_title(self, svc, repo):
        repo.next_id.return_value = 1
        task = svc.create("  spaced  ")
        assert task.title == "spaced"

    def test_rejects_empty_title(self, svc):
        with pytest.raises(ValueError, match="must not be empty"):
            svc.create("")

    def test_rejects_non_string_title(self, svc):
        with pytest.raises(ValueError, match="must be a string"):
            svc.create(123)  # type: ignore[arg-type]

    def test_rejects_too_long_title(self, repo, clock):
        svc = TaskService(repo, now=clock, max_title_length=10)
        with pytest.raises(ValueError, match="10 characters"):
            svc.create("a" * 11)

    def test_rejects_invalid_priority(self, svc, repo):
        repo.next_id.return_value = 1
        with pytest.raises(ValueError, match="TaskPriority"):
            svc.create("t", priority="high")  # type: ignore[arg-type]

    def test_rejects_naive_due_at(self, svc, repo):
        repo.next_id.return_value = 1
        with pytest.raises(ValueError, match="timezone-aware"):
            svc.create("t", due_at=datetime(2025, 1, 1))

    def test_rejects_non_datetime_due_at(self, svc, repo):
        repo.next_id.return_value = 1
        with pytest.raises(ValueError, match="must be a datetime"):
            svc.create("t", due_at="2025-01-01")  # type: ignore[arg-type]

    def test_normalizes_tags(self, svc, repo):
        repo.next_id.return_value = 1
        task = svc.create("t", tags=["Hello", "HELLO", "world"])
        assert [t.name for t in task.tags] == ["hello", "world"]

    def test_with_priority_and_due(self, svc, repo, now):
        repo.next_id.return_value = 1
        due = now + timedelta(days=1)
        task = svc.create("t", priority=TaskPriority.HIGH, due_at=due)
        assert task.priority == TaskPriority.HIGH
        assert task.due_at == due


class TestGet:
